
'use strict';
const pages={dashboard:['P01','工作台'],intelligence:['P02','X 情报'],research:['P03','研究'],watchlist:['P04','关注标的'],chat:['P05','对话'],approvals:['P06','审批'],settings:['P07','设置']};
let state,timer,toastTimer;const app=document.querySelector('main'),dialog=document.querySelector('dialog');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,act,cls='',attrs='')=>`<button data-act="${act}" class="${cls}" ${attrs}>${label}</button>`;
const badge=(s)=>{const m={queued:['排队中',''],running:['研究中',''],completed:['已完成','good'],partial:['部分完成','warn'],failed:['研究失败','bad'],cancelled:['已取消',''],awaiting_approval:['等待审批','warn'],expired:['已过期','bad'],pending:['待决定','warn'],approved:['已批准','good'],rejected:['已拒绝',''],executed:['已执行','good'],not_executed:['未执行',''],executing:['执行中',''],conflicting:['证据冲突','warn'],not_verifiable:['不可作为事实核实',''],insufficient_evidence:['证据不足','warn']};let [t,c]=m[s]||[s,''];return `<span class="badge ${c}">${t}</span>`};
const title=(s,a='')=>`<div class="title"><h1>${s}</h1>${a}</div>`;
function toast(s){clearTimeout(toastTimer);let t=document.querySelector('#toast');t.textContent=s;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,2600)}
function nav(p){state.page=p;location.hash=p;render();window.scrollTo(0,0)}
function reset(){clearTimeout(timer);if(dialog.open)dialog.close();state={page:'intelligence',accounts:[],synced:false,syncing:false,run:null,approval:null,watch:['EXM'],messages:[],context:false,filter:'',prefs:{sync:true,interval:'60',daily:true,hour:'8',zone:'Asia/Shanghai',auto:false,limit:'2'}};document.querySelector('#state').value='';nav('intelligence')}
function modal(t,b){document.querySelector('#modal-title').textContent=t;document.querySelector('#modal-body').innerHTML=b;dialog.showModal()}
function render(){document.querySelector('nav').innerHTML=Object.entries(pages).map(([key,[id,name]])=>`<a href="#${key}" ${state.page===key?'aria-current="page"':''}>${name}</a>`).join('');app.innerHTML=views[state.page]();document.title=`${pages[state.page][1]} · X Research 原型`}
function intelligence(){let body='';if(!state.accounts.length)body=`<div class="empty"><h2>暂无追踪账号</h2><p>添加一个公开账号，开始浏览帖子。</p>${btn('添加账号','add-account','primary')}</div>`;else if(!state.synced)body=`<div class="empty"><h2>${state.syncing?'正在同步':'暂无帖子'}</h2><p>${state.syncing?'保留本页，完成后即可浏览。':'账号已保存。点击同步，获取这个账号的帖子。'}</p>${btn('同步帖子','sync','primary',state.syncing?'disabled':'')}</div>`;else if(state.filter&&!['EXM','INVEST_DEMO'].some(x=>x.includes(state.filter.toUpperCase())))body=`<div class="empty"><h2>没有匹配内容</h2>${btn('清除筛选','clear-filter')}</div>`;else body=`<div class="cards"><article class="post"><div class="row"><strong>@${esc(state.accounts[0])}</strong><span class="meta">2026-08-15 10:00 CST</span></div><p>$EXM 2025 财年收入是 100 亿美元，下个月还会大涨。我长期看好存储方向。图表见原帖链接。</p><div class="notice">图片内容未纳入文字核查。</div><div class="row"><span class="badge">$EXM</span>${btn(state.run?'查看研究':'核查','check','primary')}</div></article>${!state.filter?`<article class="post"><div class="row"><strong>@${esc(state.accounts[0])}</strong><span class="meta">2026-08-15 09:00 CST</span></div><p>今天读完一本书，准备出门散步。</p><div class="row"><span class="meta">日常内容</span>${btn('核查','check-daily')}</div></article>`:''}</div>`;
return title('X 情报',btn('添加账号','add-account','primary'))+`<div class="grid"><section class="panel"><h2>关注账号</h2>${state.accounts.length?state.accounts.map(a=>`<div class="account"><strong>@${esc(a)}</strong><small>${state.synced?'最近同步 2026-08-15 10:05 CST':'尚未同步'}</small>${btn('同步','sync','',state.syncing?'disabled':'')}${btn('移除','remove-account','danger',`data-value="${esc(a)}"`)}</div>`).join(''):'<p class="meta">尚未添加</p>'}</section><section><form id="filter" class="filters"><input name="q" aria-label="按代码或账号筛选" placeholder="代码或账号" value="${esc(state.filter)}"><button>筛选</button></form>${body}</section></div>`}
function start(daily=false){if(state.run){nav('research');return}state.run={id:'RUN-DEMO-01',status:'queued',daily};nav('research');timer=setTimeout(()=>{state.run.status='running';render();timer=setTimeout(()=>{state.run.status='completed';render()},1200)},400)}
function report(){if(state.run.brief)return `<section class="panel"><h2>每日研究简报</h2><p class="meta">覆盖窗口 2026-08-14 10:08—2026-08-15 10:08 CST</p><p>覆盖标的：${state.watch.slice().reverse().slice(0,5).map(esc).join('、')}；按最近添加顺序选取，最多 5 个。</p><h3>研究线索</h3><p>EXM 收入资料存在口径冲突，需继续核对原始披露；未来上涨仍是预测。</p><div class="notice">部分外部资料未取得。简报呈现本次覆盖的研究线索，不代表所有账号的观点。</div>${btn('浏览原始观点','back-x')}</section>`;if(state.run.daily)return `<section class="panel"><h2>日常内容研究</h2><p>该帖子描述个人活动，没有可识别的投资事实断言。</p><p>本次未为日常内容调用行情或财务工具。</p>${btn('返回 X 情报','back-x')}</section>`;
return `<article class="panel report"><h2>EXM：收入与上涨观点核查</h2><p class="meta">生成于 2026-08-15 10:08 CST · 数据截至 2026-08-15</p><section><h3>研究摘要</h3><p>同一财年收入出现 100 亿与 90 亿美元两种资料，需继续核对披露口径。下个月上涨属于预测，当前资料不能证实。长期看好是个人意见。</p></section>${state.run.status==='partial'?'<div class="notice">Web 取证未完成。已取得的披露片段保留，覆盖范围有限。</div>':''}<div class="stats"><div><strong>3</strong>关键断言</div><div><strong>2</strong>来源</div><div><strong>1</strong>冲突断言</div></div><h3>关键断言</h3><details open><summary>2025 财年收入为 100 亿美元 ${badge('conflicting')}</summary><div class="detail"><p class="meta">事实 · FY2025 · USD billion</p><p>两个来源给出不同数值，需要确认披露主体和修订情况，不能简单计票。</p><div class="evidence"><strong>支持</strong><blockquote>EXM reported revenue of USD 10 billion in FY2025.</blockquote><p>主张的主体、时期和量纲与该片段一致。</p>${btn('定位来源 A','source','',`data-value="A"`)}</div><div class="evidence"><strong>反对</strong><blockquote>EXM revenue was USD 9 billion in FY2025.</blockquote><p>同期间数值不一致；对结论构成冲突。</p>${btn('定位来源 B','source','',`data-value="B"`)}</div></div></details><details><summary>下个月会大涨 ${badge('not_verifiable')}</summary><div class="detail"><p>预测 · 未来一个月。收入资料只能提供背景，不能证明未来价格。</p><p>继续核查需求、估值与市场环境等条件。</p></div></details><details><summary>长期看好存储方向 ${badge('not_verifiable')}</summary><div class="detail"><p>意见 · 没有可判定真假的标准；可以研究其依据。</p></div></details><section><h3>不确定性</h3><p>收入冲突尚未消除；图片内容未纳入；资料范围有限；价格预测不可证实。</p></section><section><h3>继续研究</h3><p>两份收入资料是否采用相同主体和修订版本？</p>${btn('携带报告继续研究','follow','primary')}${btn('导出 JSON','export')}</section><section class="sources"><h3>来源</h3>${['A','B'].map(id=>`<details id="source-${id}"><summary>来源 ${id} · ${id==='A'?'公司披露':'Web 资料'}</summary><div class="detail"><p class="meta">发布 2026-07-30 · 抓取 2026-08-15 02:06 UTC</p><blockquote>${id==='A'?'EXM reported revenue of USD 10 billion in FY2025.':'EXM revenue was USD 9 billion in FY2025.'}</blockquote></div></details>`).join('')}</section><details><summary>运行活动</summary><div class="detail"><p>读取原帖 → 提取断言 → 获取资料 → 核对引用 → 保存报告。</p><p class="meta">显示运行事件，不展示模型隐含推理。</p></div></details></article>`}
function research(){if(!state.run)return title('研究')+`<div class="empty"><h2>暂无研究</h2><p>从一条具体帖子开始。</p>${btn('浏览 X 情报','back-x','primary')}</div>`;let s=state.run.status,b='';if(['completed','partial'].includes(s))b=report();else if(['queued','running'].includes(s))b=`<section class="panel"><h2>${s==='queued'?'已提交研究':'正在核查观点'}</h2><div class="steps"><span>读取原帖</span><span>获取资料</span><span>组织报告</span></div><p>离开页面不会取消任务。</p>${btn('取消研究','cancel','danger')}</section>`;else if(s==='awaiting_approval')b=`<section class="panel"><h2>需要审批</h2><p>请确认拟写入的个人资料参数。</p>${btn('查看审批','go-approvals','primary')}</section>`;else b=`<section class="panel"><h2>${({failed:'研究未完成',cancelled:'研究已取消',expired:'审批已过期'})[s]}</h2><p>${({failed:'外部资料获取超时，未形成报告。',cancelled:'已停止启动新的工具调用。',expired:'原审批不可继续执行，请重新提出研究意图。'})[s]}</p>${btn('重新研究','retry','primary')}${btn('返回帖子','back-x')}</section>`;return title('研究',badge(s))+b}
function dashboard(){return title('工作台')+`<div class="stats"><section class="panel"><span>关注账号</span><strong>${state.accounts.length}</strong></section><section class="panel"><span>研究任务</span><strong>${state.run?1:0}</strong></section><section class="panel"><span>待审批</span><strong>${state.approval?.decision==='pending'?1:0}</strong></section></div><div class="equal"><section class="panel"><h2>最近研究</h2><p>${state.run?'EXM 投资观点':'暂无研究记录'}</p>${state.run?badge(state.run.status):''}<div class="actions">${btn(state.run?'查看研究':'浏览帖子',state.run?'go-research':'back-x','primary')}</div></section><section class="panel"><h2>每日简报</h2><p>最近添加的最多 5 个标的 · 过去 24 小时。</p>${btn('生成简报','brief')}</section></div>`}
function watchlist(){return title('关注标的',btn('添加标的','add-watch','primary'))+`<div class="grid"><section class="panel"><h2>标的列表</h2>${state.watch.map(x=>`<p><strong>${esc(x)}</strong></p>`).join('')||'<p>暂无标的</p>'}</section><section class="panel"><h2>EXM · 示例存储公司</h2><p class="price">USD 100.00</p><p>上一交易日收盘 · 2026-08-14</p><p class="meta">非实时 · 已复权 · 抓取 2026-08-15 02:06 UTC</p><div class="table-wrap"><table><tr><th>开盘</th><th>成交量</th><th>较当日开盘</th></tr><tr><td>USD 98.00</td><td>1,200,000 股</td><td>+2.04%</td></tr></table></div><div class="notice">此变化为开盘到收盘，不是相对上一日收盘。</div><h3>相关研究</h3>${btn('查看报告','go-research')}</section></div>`}
function approvalCard(){let a=state.approval;if(!a)return '<p>暂无待审批动作。</p>';return `<section class="panel"><div class="row"><h2>加入关注标的</h2>${badge(a.decision)}</div><p class="meta">审批 AP-DEMO-01 · 到期 2026-08-18 10:08 CST</p><p>将所选标的保存至个人关注列表。</p><pre>${esc(JSON.stringify(a.args,null,2))}</pre><p>执行状态：${badge(a.execution)}</p>${a.decision==='pending'?`<div class="actions">${btn('批准','approve','primary')}${btn('编辑并批准','edit')}${btn('拒绝','reject','danger')}</div>`:''}</section>`}
function chat(){return title('对话')+`<section class="panel">${state.context?`<div class="context"><div class="row"><strong>上下文：EXM 观点核查报告</strong>${btn('移除','remove-context')}</div><small>RUN-DEMO-01 · 3 条断言 · 2 个来源</small></div>`:''}${state.messages.map(m=>`<div class="message ${m.role}"><strong>${m.role==='user'?'你':'研究助手'}</strong>\n${esc(m.text)}</div>`).join('')||'<p>继续核对来源，或提出新的研究问题。</p>'}${state.approval?approvalCard():''}<form id="chat-form"><label for="message">研究问题</label><textarea id="message" name="message" maxlength="6000" required placeholder="例如：两份收入资料有什么口径差异？"></textarea><div class="actions"><button class="primary" ${state.approval?.decision==='pending'?'disabled':''}>发送</button>${btn('提议加入关注列表','propose')}</div></form></section>`}
function approvals(){return title('审批')+approvalCard()}
function settings(){let p=state.prefs;return title('设置')+`<div class="equal"><form id="prefs" class="panel"><h2>研究偏好</h2><label class="check"><input type="checkbox" name="sync" ${p.sync?'checked':''}>自动同步</label><label>同步间隔（分钟）<input type="number" name="interval" min="30" max="1440" value="${p.interval}" required></label><label class="check"><input type="checkbox" name="daily" ${p.daily?'checked':''}>站内每日简报</label><label>简报时刻（小时）<input type="number" name="hour" min="0" max="23" value="${p.hour}" required></label><label>时区<select name="zone">${['Asia/Shanghai','America/New_York','UTC'].map(z=>`<option ${p.zone===z?'selected':''}>${z}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="auto" ${p.auto?'checked':''}>自动研究匹配帖子</label><label>每日自动研究上限<input type="number" name="limit" min="0" max="10" value="${p.limit}" required></label><button class="primary">保存设置</button></form><section class="panel"><h2>数据连接</h2><p>Qwen · 理解与组织</p><p>Tavily · Web 取证</p><p>X · 公开帖子</p><p>SEC · 公司披露</p><p>Massive · 行情</p><p class="meta">离线原型不连接外部服务。</p></section></div>`}
const views={dashboard,intelligence,research,watchlist,chat,approvals,settings};
function propose(){if(state.approval?.decision==='pending'){toast('已有待决定动作');return}state.approval={decision:'pending',execution:'not_executed',args:{ticker:'DEMO',company_name:'示例公司',notes:'由报告研究提出'}};if(!state.run)state.run={id:'RUN-DEMO-01',status:'awaiting_approval'};state.messages.push({role:'assistant',text:'拟将 DEMO 加入关注列表，请确认参数。'});render()}
function decide(yes,args){let a=state.approval;if(!a||a.decision!=='pending')return; a.decision=yes?'approved':'rejected';if(args)a.args=args;a.execution=yes?'executing':'not_executed';render();if(yes)timer=setTimeout(()=>{a.execution='executed';if(!state.watch.includes(a.args.ticker))state.watch.push(a.args.ticker);render();toast('已在原型中执行')},600);else toast('已拒绝，未执行')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;let act=b.dataset.act,v=b.dataset.value;if(act==='add-account')modal('添加公开账号',`<form id="account-form"><label>账号<input name="username" value="invest_demo" pattern="@?[A-Za-z0-9_]{1,15}" maxlength="16" required></label><p class="meta">支持公开账号；保存后需要同步帖子。</p><button class="primary">添加</button></form>`);if(act==='remove-account')modal('移除追踪',`<p>停止同步 @${esc(v)} 的新帖子。</p>${btn('确认移除','confirm-remove','danger',`data-value="${esc(v)}"`)}`);if(act==='confirm-remove'){state.accounts=state.accounts.filter(a=>a!==v);dialog.close();render()}
if(act==='sync'){if(state.syncing||!state.accounts.length)return;state.syncing=true;render();timer=setTimeout(()=>{state.syncing=false;state.synced=true;render();toast('同步完成，2 条帖子')},600)}if(act==='check')start();if(act==='check-daily')modal('核查日常内容','<p>这条帖子没有明显投资断言。仍可提交文字研究。</p>'+btn('继续核查','daily-confirm'));if(act==='daily-confirm'){dialog.close();state.run=null;start(true)}if(act==='clear-filter'){state.filter='';render()}if(act==='back-x')nav('intelligence');if(act==='go-research'){if(!state.run)state.run={id:'RUN-DEMO-01',status:'completed'};nav('research')}if(act==='go-approvals')nav('approvals');if(act==='cancel'){clearTimeout(timer);state.run.status='cancelled';render();toast('研究已取消')}if(act==='retry'){clearTimeout(timer);state.run=null;start()}
if(act==='source'){let s=document.querySelector('#source-'+v);s.open=true;s.scrollIntoView({behavior:'auto',block:'center'});s.querySelector('summary').focus()}if(act==='follow'){state.context=true;state.messages=[{role:'assistant',text:'已带入报告上下文。你想继续核查哪项条件或口径？'}];nav('chat')}if(act==='remove-context'){state.context=false;render()}if(act==='propose')propose();if(act==='approve')decide(true);if(act==='reject')decide(false);if(act==='edit'){let a=state.approval;modal('编辑并批准',`<form id="edit-form"><label>股票代码<input name="ticker" value="${esc(a.args.ticker)}" pattern="[A-Za-z][A-Za-z0-9.\-]{0,14}" maxlength="15" required></label><label>备注<textarea name="notes" maxlength="4000">${esc(a.args.notes)}</textarea></label><button class="primary">确认编辑并批准</button></form>`)}if(act==='add-watch')modal('添加关注标的','<form id="watch-form"><label>股票代码<input name="ticker" pattern="[A-Za-z][A-Za-z0-9.\-]{0,14}" maxlength="15" required></label><button class="primary">添加</button></form>');if(act==='brief'){if(!state.watch.length)return toast('请先添加关注标的');state.run={id:'RUN-DEMO-BRIEF',status:'partial',brief:true};nav('research')}
if(act==='export'){let blob=new Blob([JSON.stringify({version:'demo-v1',report_id:'RUN-DEMO-01',generated_at:'2026-08-15T02:08:00Z',data_cutoff:'2026-08-15',claims:[{text:'FY2025收入100亿美元',kind:'fact',status:'conflicting',evidence:[{source_id:'A',stance:'support',quote:'EXM reported revenue of USD 10 billion in FY2025.'},{source_id:'B',stance:'contradict',quote:'EXM revenue was USD 9 billion in FY2025.'}]},{text:'下月上涨',kind:'prediction',status:'not_verifiable'},{text:'长期看好',kind:'opinion',status:'not_verifiable'}],sources:[{source_id:'A',source_type:'sec',excerpt:'EXM reported revenue of USD 10 billion in FY2025.',published_at:'2026-07-30',retrieved_at:'2026-08-15T02:06:00Z'},{source_id:'B',source_type:'web',excerpt:'EXM revenue was USD 9 billion in FY2025.',published_at:'2026-07-30',retrieved_at:'2026-08-15T02:06:00Z'}]},null,2)],{type:'application/json'});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='EXM-report-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=new FormData(f);if(!f.reportValidity())return;if(f.id==='account-form'){let u=String(d.get('username')).trim().replace(/^@/,'');if(!/^[A-Za-z0-9_]{1,15}$/.test(u))return;if(state.accounts.includes(u)){dialog.close();toast('账号已在列表中');return}state.accounts.push(u);state.synced=false;dialog.close();render();toast('账号已添加，请同步帖子')}
if(f.id==='filter'){state.filter=String(d.get('q')).trim();render()}if(f.id==='chat-form'){let m=String(d.get('message')).trim();if(!m)return;state.messages.push({role:'user',text:m});state.messages.push({role:'assistant',text:state.context?'本轮将继续核对报告中的收入口径与修订版本；原报告保持其自身截至日期。':'请明确核查主体、时期和依据，以便组织研究。'});render()}if(f.id==='edit-form'){dialog.close();decide(true,{...state.approval.args,ticker:String(d.get('ticker')).toUpperCase(),notes:String(d.get('notes'))})}if(f.id==='watch-form'){let t=String(d.get('ticker')).toUpperCase();if(!state.watch.includes(t))state.watch.push(t);dialog.close();render();toast('标的已添加')}if(f.id==='prefs'){state.prefs={sync:d.has('sync'),interval:String(d.get('interval')),daily:d.has('daily'),hour:String(d.get('hour')),zone:String(d.get('zone')),auto:d.has('auto'),limit:String(d.get('limit'))};toast('设置已保存于当前演示');render()}});
document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#reset').onclick=reset;document.querySelector('#state').onchange=e=>{clearTimeout(timer);let v=e.target.value;if(!v)return;if(v==='empty')return reset();state.run={id:'RUN-DEMO-01',status:v};if(v==='awaiting_approval'){propose();state.run.status=v;nav('approvals')}else{if(v==='expired')state.approval={decision:'expired',execution:'not_executed',args:{ticker:'DEMO',notes:'期限已过'}};nav('research')}};window.onhashchange=()=>{let p=location.hash.slice(1);if(pages[p]){state.page=p;render()}};reset();
